const matrixNames={highest:'Highest Slab',all:'Highest Slab — Pay for All',only:'Highest Slab — Slab Units Only',tiered:'Tiered'};
const performanceSlabs=c=>c.basis==='Performance'&&payoutType(c)!=='Minimum Guarantee'&&c.rules.length>0;
function ensureMatrix(c){if(!performanceSlabs(c))return;c.payoutOptions||=['Lump Sum','Variable'];c.payoutField||=c.primary;c.lumpOptions||=['highest','tiered'];c.variableOptions||=['all','only','tiered'];c.payoutType||='Lump Sum';c.matrixBehaviour||=c.rules.some(r=>r.exclude==='Any subsequent slab achieved')?'highest':'tiered';if(!c.payoutOptions.includes(c.payoutType))c.payoutType=c.payoutOptions[0];const allowed=c.payoutType==='Lump Sum'?c.lumpOptions:variableChoices(c);if(!allowed.includes(c.matrixBehaviour))c.matrixBehaviour=allowed[0];}
function variableChoices(c){const f=sharedKeys.find(f=>f.id===c.payoutField);return (c.variableOptions||[]).filter(x=>x==='all'||(f?.type!=='Percentage'&&c.payoutField===c.primary));}
function matrixChecks(c,i,key,options){return `<div class="field-list">${options.map(o=>{const id=typeof o==='string'?o:o.id,label=typeof o==='string'?o:o.name;return `<label><input type="checkbox" data-matrix-check="${i}|${key}|${id}" ${c[key].includes(id)?'checked':''}>${esc(label)}</label>`}).join('')}</div>`}
function matrixAdmin(c,i){ensureMatrix(c);const available=sharedKeys.filter(f=>[c.primary,...c.keys].includes(f.id));const fraction=sharedKeys.find(f=>f.id===c.payoutField)?.type==='Percentage';return `<section class="panel"><div class="panel-head"><h3>Payout</h3></div><div class="panel-body"><div class="grid"><div><label>Payout Types ${help('Choose the types available to the Manager.')}</label>${matrixChecks(c,i,'payoutOptions',['Lump Sum',{id:'Variable',name:'Variable (Per Unit)'}])}</div>${c.payoutOptions.includes('Variable')?select('Payout Field',`components.${i}.payoutField`,available,c.payoutField,'The performance quantity multiplied by the selected rate.'):''}</div><label class="section-gap">Applicable Matrix</label>${c.payoutOptions.includes('Lump Sum')?`<p class="quiet">LUMP SUM</p>${matrixChecks(c,i,'lumpOptions',[{id:'highest',name:matrixNames.highest},{id:'tiered',name:matrixNames.tiered}])}`:''}${c.payoutOptions.includes('Variable')?`<p class="quiet">VARIABLE</p>${matrixChecks(c,i,'variableOptions',(fraction||c.payoutField!==c.primary?['all']:['all','only','tiered']).map(id=>({id,name:matrixNames[id]})))}${fraction?'<p class="quiet">Percentage fields support Pay for All only.</p>':c.payoutField!==c.primary?'<p class="quiet">Slab-unit behaviours require the Payout Field to match the Primary Field.</p>':''}`:''}<p class="quiet">Targets and amounts are entered in the template.</p></div></section>`}
const beforeMatrixComponent=componentForm;
componentForm=function(c,i){if(!performanceSlabs(c))return beforeMatrixComponent(c,i);ensureMatrix(c);return `<section class="panel component"><div class="panel-head"><h3>${esc(c.name)}</h3>${btn('Remove','remove-component',i)}</div><div class="panel-body"><div class="grid">${input('Name',`components.${i}.name`,c.name)}<label>Type<select data-simple-type="${i}">${opts(payoutTypes,'Performance-based')}</select></label>${select('Operator',`components.${i}.effect`,['Add','Deduct'],c.effect)}${select('Primary Field',`components.${i}.primary`,sharedKeys,c.primary)}<label>Payment<select data-performance-mode="${i}">${opts(['Per quantity','By targets'],'By targets')}</select></label></div><label class="section-gap">Other Fields</label><div class="field-list">${sharedKeys.filter(f=>f.id!==c.primary).map(f=>`<label><input type="checkbox" data-c-key="${i}|${f.id}" ${c.keys.includes(f.id)?'checked':''}>${esc(f.name)}</label>`).join('')}</div>${matrixAdmin(c,i)}<details><summary>Field filters</summary>${performanceFilters(c,i)}</details></div></section>`};
function matrixSummary(c){if(c.payoutType==='Lump Sum')return c.matrixBehaviour==='tiered'?'Sum of rewards for all achieved slabs.':'Reward for the highest achieved slab.';if(c.matrixBehaviour==='all')return `Highest achieved rate × ${displayKey(c.payoutField)}.`;return c.matrixBehaviour==='only'?'Highest achieved rate × units above its target.':'Sum of each slab’s rate × units between its target and the next target.';}
const beforeMatrixRules=ruleForm;
ruleForm=function(c,i,manager){if(!manager||!performanceSlabs(c))return beforeMatrixRules(c,i,manager);ensureMatrix(c);const def=structure(draft.structure)?.components.find(x=>x.id===c.id);if(def){ensureMatrix(def);c.payoutOptions=clone(def.payoutOptions);c.lumpOptions=clone(def.lumpOptions);c.variableOptions=clone(def.variableOptions);c.payoutField=def.payoutField;ensureMatrix(c)}for(const r of c.rules){if(r.secondary){r.targets||={};if(!Object.hasOwn(r.targets,r.secondary))r.targets[r.secondary]=r.secondaryMax;r.secondary='';}}const keyIds=[...new Set([c.primary,...c.keys])];return `<div class="grid">${select('Payout Type',`components.${i}.payoutType`,c.payoutOptions.map(id=>({id,name:id==='Variable'?'Variable (Per Unit)':id})),c.payoutType)}${select('Matrix Behaviour',`components.${i}.matrixBehaviour`,(c.payoutType==='Lump Sum'?c.lumpOptions:variableChoices(c)).map(id=>({id,name:matrixNames[id]})),c.matrixBehaviour)}</div><p class="quiet">Primary Field: <strong>${esc(displayKey(c.primary))}</strong>${c.payoutType==='Variable'?` · Payout Field: <strong>${esc(displayKey(c.payoutField))}</strong>`:''}</p>${table(['Slab',...keyIds.map(k=>esc(displayKey(k))+' ≥'),c.payoutType==='Lump Sum'?'Amount':'Rate',''],c.rules.map((r,j)=>row([j+1,...keyIds.map(k=>`<input type="number" min="0" step="${sharedKeys.find(f=>f.id===k)?.type==='Integer'?'1':'any'}" data-k="components.${i}.rules.${j}.${k===c.primary?'max':'targets.'+k}" value="${esc(k===c.primary?r.max:r.targets?.[k]??(r.secondary===k?r.secondaryMax:''))}" placeholder="${k===c.primary?'Required':'Optional'}" aria-label="Slab ${j+1} ${esc(displayKey(k))}">`),`<input type="number" min="0" step="any" data-k="components.${i}.rules.${j}.value" value="${esc(r.value)}" aria-label="Slab ${j+1} reward">`,btn('Remove','remove-rule',`${i}|${j}`)])))}${btn('+ Add slab','add-rule',i)}<div class="formula">${esc(matrixSummary(c))}</div>`};
function compileMatrix(c){if(!performanceSlabs(c))return c;ensureMatrix(c);const out=clone(c);out.keys=[...new Set([...out.keys,out.payoutField])];out.rules=out.rules.map((r,j)=>{const target=r.max,next=out.rules[j+1]?.max;const quantity=next==null?`MAX(0, ${c.primary} - ${target})`:`MAX(0, MIN(${c.primary}, ${next}) - ${target})`;return {...r,min:0,when:'Slab achieved',exclude:c.matrixBehaviour==='tiered'?'NA':'Any subsequent slab achieved',formula:c.payoutType==='Lump Sum'?'value':c.matrixBehaviour==='all'?`value * ${c.payoutField}`:`value * ${quantity}`,valueType:'Float'};});return out;}
const beforeMatrixCalculate=calculate;
calculate=function(t,u){return beforeMatrixCalculate({...t,components:t.components.map(compileMatrix)},u)};
const beforeMatrixValidate=validateStructure;
validateStructure=function(s){for(const c of s.components){if(!performanceSlabs(c))continue;ensureMatrix(c);if(!c.payoutOptions.length||c.payoutOptions.includes('Lump Sum')&&!c.lumpOptions.length||c.payoutOptions.includes('Variable')&&!variableChoices(c).length)throw Error('Select a behaviour for each enabled payout type.');if(![c.primary,...c.keys].includes(c.payoutField))throw Error('Payout Field must be a selected performance field.');if(editorType==='template'){let prev=-1;for(const r of c.rules){if(!Number.isFinite(r.max)||r.max<=prev||r.max<=0)throw Error('Slab targets must be positive and increase.');prev=r.max;for(const [key,v] of Object.entries(r.targets||{})){if(v===''||v==null||Number.isNaN(v))continue;if(!Number.isFinite(v)||v<0||sharedKeys.find(f=>f.id===key)?.type==='Integer'&&!Number.isInteger(v))throw Error('Enter valid additional targets.');}}}}beforeMatrixValidate({...s,components:s.components.map(compileMatrix)});};
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.matrixCheck){const [i,key,value]=el.dataset.matrixCheck.split('|'),c=draft.components[i];c[key]=el.checked?[...new Set([...c[key],value])]:c[key].filter(x=>x!==value);structureForm();return}if(el.dataset.k&&/\.(payoutField|payoutType|matrixBehaviour)$/.test(el.dataset.k)){const c=draft.components[Number(el.dataset.k.split('.')[1])];ensureMatrix(c);editorType==='structure'?structureForm():templateForm();return}if(el.dataset.cKey&&editorType==='structure'){structureForm();}});
render();
